p=Path('index.html');s=p.read_text(encoding='utf-8');s=s.replace('<div id="toast" class="toast" role="status" aria-live="polite"></div>','');s=s.replace('<dialog id="help-dialog">','<dialog id="hint-dialog"><button id="close-hint" class="close" aria-label="Close hint">×</button><span class="eyebrow">QUEST LOG · GAME PAUSED</span><h2>A little teamwork.</h2><p id="hint-objective"></p><span class="eyebrow">LATEST CLUE</span><p id="toast" class="toast" role="status"></p><button id="resume-hint">BACK TO THE GAME ▶</button></dialog><dialog id="help-dialog">');p.write_text(s,encoding='utf-8')
